import { useQueryClient } from '@tanstack/react-query';
import { useEffect } from 'react';
import { voucherApi } from '~/entities/voucher/api/voucher-api';
import { VOUCHER_LIST_PAGING } from '~/entities/voucher/model/constants';
import { queries } from '~/shared/api/query-keys';

type UsePrefetchIssuedVoucherParams = {
  hasWallet: boolean;
  cstmrNo?: string | null;
  userAliasNm?: string | null;
};

export const usePrefetchIssuedVoucher = ({ hasWallet, cstmrNo, userAliasNm }: UsePrefetchIssuedVoucherParams) => {
  const queryClient = useQueryClient();

  useEffect(() => {
    if (hasWallet) {
      const params = {
        paging: { ...VOUCHER_LIST_PAGING },
        aliasNm: 'ALL',
        cstmrNo,
        userAliasNm
      };

      queryClient.prefetchInfiniteQuery({
        queryKey: queries.voucher.issuedVoucherList(params).queryKey,
        queryFn: () =>
          voucherApi.getIssuedVoucherList({
            paging: params.paging,
            aliasNm: params.aliasNm,
          }),
        initialPageParam: params,
        staleTime: 1000 * 60,
      });
    }
  }, [queryClient, hasWallet, cstmrNo, userAliasNm]);
};
