import { useEffect } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { notiBar } from '~/shared/lib';

export const useNotiBar = () => {
  const [notiBarMessage, setNotiBarMessage] = useStore(
    useShallow((state) => [state.appConfigSlice.notiBarMessage, state.appConfigSlice.setNotiBarMessage]),
  );

  useEffect(() => {
    if (notiBarMessage) {
      notiBar(notiBarMessage);
      setNotiBarMessage('');
    }
  }, [notiBarMessage]);
};
