import { ErrorBoundary, Suspense } from '@suspensive/react';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { refetchHistoryList } from '~/entities/wallet/api/use-wallet-history-list-query';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { WalletHistoryViewType } from '~/entities/wallet/types';
import { TokenItemType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';
import { RecentUseHistoryContent } from './recent-use-history-content';

export const RecentUseHistory = () => {
  const { navigate } = useNavigate();
  const { data: userRes } = useGetUserInfoQuery();
  const { aliasNm, priAliasNm } = userRes?.tbCstmrMastr ?? {};
  const myBankCode = appConfig.BANK_CODE ?? '';

  const goToHistory = () => {
    navigate(
      `${PATHS.myWallet.history}?coinType=${TokenItemType.DC1}&walletInsttCd=${myBankCode}&coinId=0&aliasNm=${priAliasNm ?? aliasNm}&viewType=${WalletHistoryViewType.TOKEN_HISTORY}`,
    );
  };

  return (
    <section className="main-transactions-container">
      <div className="main-transactions-card">
        <div className="main-transactions-title-wrapper">
          <span className="main-transactions-title">최근 이용내역</span>
          <button type="button" className="btn-main-transactions-more" onClick={goToHistory}>
            <span className="main-transactions-more">더보기</span>
            <i className="icon-main-transactions-more"></i>
          </button>
        </div>
        <ErrorBoundary fallback={FallbackErrorMessage}>
          <Suspense fallback={<LoadingSpinner />}>
            <RecentUseHistoryContent />
          </Suspense>
        </ErrorBoundary>
      </div>
    </section>
  );
};
