import { useSuspenseQuery } from '@tanstack/react-query';
import { DEFAULT_RECENT_PAGING, DEFAULT_RECENT_SEARCH } from '~/entities/wallet/api/dtos/constants';
import {
  WalletHistoryListRequestDTO,
  WalletHistoryListResponseDTO,
} from '~/entities/wallet/api/dtos/wallet-history-list';
import { walletApi } from '~/entities/wallet/api/wallet-api';
import { restructureList } from '~/entities/wallet/lib/restructure-list';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';

export const useWalletHistoryListQuery = (
  { paging = DEFAULT_RECENT_PAGING, search = DEFAULT_RECENT_SEARCH }: WalletHistoryListRequestDTO,
  options?: QueryOptions<WalletHistoryListResponseDTO, CBDCAxiosError>,
) => {
  return useSuspenseQuery<WalletHistoryListResponseDTO, CBDCAxiosError>({
    queryKey: queries.wallet.walletHistoryList({ paging, search }).queryKey,
    queryFn: () => walletApi.getWalletHistoryList({ paging, search }),
    select: (data) => {
      data.result.newList = restructureList(data.result.list);
      return data;
    },
    enabled: !!paging && !!search,
    gcTime: 0,
    staleTime: 0,
    refetchOnWindowFocus: 'always',
    refetchOnMount: 'always',
    refetchOnReconnect: 'always',
    ...options,
  });
};

export const refetchHistoryList = () => {
  const queryClient = getGlobalQueryClient();
  queryClient.invalidateQueries({ queryKey: queries.wallet.walletHistoryList._def });
};
