import { ErrorBoundary, Suspense } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';
import { NoticeContent } from './notice-content';

export const Notice = () => {
  const { navigate } = useNavigate();

  return (
    <section className="main-notice-container">
      <div className="main-notice-card">
        <div className="main-notice-title-wrapper">
          <span className="main-notice-title">공지사항</span>
          <button type="button" className="btn-main-notice-more" onClick={() => navigate(PATHS.community.notice)}>
            <span className="main-notice-more">더보기</span>
            <i className="icon-main-notice-more"></i>
          </button>
        </div>
        <div className="main-notice-wrapper">
          <QueryErrorResetBoundary>
            {({ reset }) => (
              <ErrorBoundary fallback={FallbackErrorMessage} onReset={reset}>
                <Suspense fallback={<LoadingSpinner />}>
                  <NoticeContent />
                </Suspense>
              </ErrorBoundary>
            )}
          </QueryErrorResetBoundary>
        </div>
      </div>
    </section>
  );
};
